import { Group, Mesh, CylinderGeometry, OctahedronGeometry, PlaneGeometry, DirectionalLight, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, Vector2, MathUtils } from 'three/webgpu';
import { uv, mix, smoothstep, vec3, color } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<{name:string, params:Object, trigger:string}>} cinematicPrimitives
 * @property {Array<{text:string, role:string, typography?:{fontSize:number}}>} textContent
 * @property {Object} intent
 * @property {Object} intent.visualSpec
 * @property {Array<{at:number, hex:string}>} intent.visualSpec.gradientStops
 * @property {Object} intent.visualSpec.colors
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} fontAtlas
 * @property {Function} emit
 * @property {Object} primitives
 * @property {Object} [videoLoader]
 * @property {'T0'|'T1'|'T2'} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new Group();

  // ---------- BACKDROP GRADIENT ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const yNode = uv().y;
  const stops = (config.intent?.visualSpec?.gradientStops) ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.6, hex: '#12121a' },
    { at: 1, hex: '#16161d' },
  ];
  let gradNode = color(stops[0].hex);
  for (let i = 1; i < stops.length; i++) {
    const prev = stops[i - 1];
    const cur = stops[i];
    const t = smoothstep(prev.at, cur.at, yNode);
    gradNode = mix(gradNode, color(cur.hex), t);
  }
  backdropMat.colorNode = gradNode;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- PRISM ----------
  const side = 1.2;
  const radius = side / Math.sqrt(3);
  const prismGeom = new CylinderGeometry(radius, radius, 1.8, 3, 1, true);
  const prismMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    metalness: 0.0,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color('#e8ecf2'),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: new Vector2(0.12, 0.48),
    color: new Color('#16161d'),
  });
  const prism = new Mesh(prismGeom, prismMat);
  prism.rotation.z = MathUtils.degToRad(12);
  prism.rotation.y = MathUtils.degToRad(20);
  root.add(prism);

  // ---------- EMISSIVE CORE ----------
  const coreGeom = new OctahedronGeometry(0.35);
  const coreMat = new MeshStandardNodeMaterial({
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 2.2,
    metalness: 0.0,
    roughness: 0.5,
    color: new Color('#000000'),
  });
  const core = new Mesh(coreGeom, coreMat);
  root.add(core);

  // ---------- BACK RIM LIGHT ----------
  const rimLight = new DirectionalLight('#e8ecf2', 0.8);
  rimLight.position.set(-5, -5, 5);
  rimLight.target = prism;
  root.add(rimLight);
  root.add(rimLight.target);

  // ---------- CAUSTIC STREAK ----------
  const causticGeom = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.35 });
  const xNode = uv().x;
  const causticStops = [
    { at: 0.2, hex: '#ff2a38' },
    { at: 0.5, hex: '#e8ecf2' },
    { at: 0.8, hex: '#9fb0c4' },
  ];
  let causticNode = color(causticStops[0].hex);
  for (let i = 1; i < causticStops.length; i++) {
    const prev = causticStops[i - 1];
    const cur = causticStops[i];
    const t = smoothstep(prev.at, cur.at, xNode);
    causticNode = mix(causticNode, color(cur.hex), t);
  }
  causticMat.colorNode = causticNode;
  const caustic = new Mesh(causticGeom, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0);
  root.add(caustic);

  // ---------- TEXT ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {};
  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 68,
      color: item.role === 'headline' ? colors.ink ?? '#16161d' : colors.paper ?? '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    if (item.role === 'headline') {
      txtObj.position.set(0, -1.75, 0);
    } else if (item.role === 'caption') {
      txtObj.position.set(0, -2.25, 0);
    } else {
      txtObj.position.set(0, 0, 0);
    }
    root.add(txtObj);
  }

  // ---------- CINEMATIC PRIMITIVES ----------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name];
      if (typeof handler === 'function') {
        const handle = handler(root, prim.params);
        primitiveHandles.push(handle);
      }
    }
  }

  // ---------- ENTRANCE ANIMATION ----------
  const entrance = gsap.timeline();
  entrance.from(root.position, { y: 0.4, duration: 0.7, ease: 'power3.out' });
  entrance.from(
    root.scale,
    { x: 0.8, y: 0.8, z: 0.8, duration: 0.7, ease: 'power3.out' },
    '<'
  );

  // ---------- USERDATA ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    entrance.kill();
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') ph.cleanup();
    }
    backdropGeom.dispose();
    backdropMat.dispose();
    prismGeom.dispose();
    prismMat.dispose();
    coreGeom.dispose();
    coreMat.dispose();
    causticGeom.dispose();
    causticMat.dispose();
  };

  return root;
}
